// SMS send gate. Decides whether one text may go out right now.
// Fails closed: anything unclear holds the text with a named rule.
//
// Rules (47 CFR 64.1200 and CTIA Messaging Principles and Best Practices):
//   invalid-input       user or message is malformed
//   invalid-kind        message.kind is not "marketing" or "transactional"
//   empty-message       text is not a non-blank string
//   opted-out           optedOutAt is set (customer replied STOP); holds every kind
//   no-consent          marketing text, but user.sms.optedIn is not exactly true
//   no-opt-out-notice   marketing text does not tell the customer how to opt out
//   invalid-time        marketing text, but `now` is not a valid Date
//   unknown-time-zone   marketing text, but the customer's time zone is missing,
//                       invalid, or a UTC/GMT placeholder, so local time is unknown
//   quiet-hours         marketing text, customer's local time outside 08:00-21:00
//   internal-error      unexpected failure while checking

const WINDOW_START_MINUTES = 8 * 60; // 08:00 local, inclusive
const WINDOW_END_MINUTES = 21 * 60; // 21:00 local, exclusive

// Placeholders that mean "server default", not a customer's real location.
const PLACEHOLDER_ZONE = /^(utc|gmt|z|zulu|uct|universal|greenwich|etc\/.*)$/i;

const hold = (rule) => ({ allowed: false, rule });
const ALLOW = Object.freeze({ allowed: true, rule: '' });

function isObject(value) {
  return typeof value === 'object' && value !== null;
}

// Returns minutes since local midnight, or null if the zone is unusable.
function localMinutes(timeZone, now) {
  if (typeof timeZone !== 'string') return null;
  const zone = timeZone.trim();
  if (zone === '' || PLACEHOLDER_ZONE.test(zone)) return null;
  // Fixed offsets such as "+05:00" are not IANA names and ignore DST.
  if (!/^[A-Za-z]/.test(zone)) return null;
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: zone,
      hourCycle: 'h23',
      hour: 'numeric',
      minute: 'numeric',
    }).formatToParts(now);
    const hour = Number(parts.find((p) => p.type === 'hour')?.value);
    const minute = Number(parts.find((p) => p.type === 'minute')?.value);
    if (!Number.isInteger(hour) || !Number.isInteger(minute)) return null;
    return hour * 60 + minute;
  } catch {
    return null;
  }
}

// Marketing text must tell the customer how to stop (CTIA opt-out guidance).
function hasOptOutNotice(text) {
  return /\bstop\b/i.test(text);
}

export async function checkSend({ user, message, now } = {}) {
  try {
    if (!isObject(user) || !isObject(message)) return hold('invalid-input');

    const { kind, text } = message;
    if (kind !== 'marketing' && kind !== 'transactional') return hold('invalid-kind');
    if (typeof text !== 'string' || text.trim() === '') return hold('empty-message');

    const sms = user.sms;
    if (!isObject(sms)) return hold(kind === 'marketing' ? 'no-consent' : 'invalid-input');

    // Any value other than null/undefined counts as a STOP, even a malformed
    // timestamp or one dated in the future.
    if (sms.optedOutAt !== null && sms.optedOutAt !== undefined) return hold('opted-out');

    if (kind === 'transactional') return ALLOW;

    // Marketing from here on.
    if (sms.optedIn !== true) return hold('no-consent');
    if (!hasOptOutNotice(text)) return hold('no-opt-out-notice');

    if (!(now instanceof Date) || Number.isNaN(now.getTime())) return hold('invalid-time');

    const minutes = localMinutes(user.timeZone, now);
    if (minutes === null) return hold('unknown-time-zone');
    if (minutes < WINDOW_START_MINUTES || minutes >= WINDOW_END_MINUTES) return hold('quiet-hours');

    return ALLOW;
  } catch {
    return hold('internal-error');
  }
}

import assert from 'node:assert/strict';
import { checkSend } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/courier-d1-3/bot.mjs';

const mk = (o = {}) => ({ id: 'u', timeZone: 'America/Chicago', sms: { optedIn: true, optedOutAt: null }, ...o });
const mkt = { kind: 'marketing', text: 'Sale! 20% off. Reply STOP to opt out.' };
const trx = { kind: 'transactional', text: 'Your box shipped.' };
const t = (s) => new Date(s);
const cases = [
  // Chicago CDT = UTC-5 in Oct. 14:00Z = 09:00 local
  [mk(), mkt, t('2026-10-23T14:00:00Z'), true, ''],
  [mk(), mkt, t('2026-10-23T12:59:00Z'), false, 'quiet-hours'], // 07:59
  [mk(), mkt, t('2026-10-23T13:00:00Z'), true, ''], // 08:00
  [mk(), mkt, t('2026-10-24T01:59:00Z'), true, ''], // 20:59
  [mk(), mkt, t('2026-10-24T02:00:00Z'), false, 'quiet-hours'], // 21:00
  [mk(), mkt, t('2026-10-24T05:00:00Z'), false, 'quiet-hours'],
  // DST: Chicago CST after 2026-11-01 = UTC-6; 14:00Z = 08:00
  [mk(), mkt, t('2026-11-02T14:00:00Z'), true, ''],
  [mk(), mkt, t('2026-11-02T13:59:00Z'), false, 'quiet-hours'],
  // Tokyo (UTC+9): 00:00Z = 09:00
  [mk({ timeZone: 'Asia/Tokyo' }), mkt, t('2026-10-23T00:00:00Z'), true, ''],
  [mk({ timeZone: 'Asia/Tokyo' }), mkt, t('2026-10-23T14:00:00Z'), false, 'quiet-hours'], // 23:00
  // Kolkata (+5:30): 03:30Z = 09:00
  [mk({ timeZone: 'Asia/Kolkata' }), mkt, t('2026-10-23T03:30:00Z'), true, ''],
  [mk({ timeZone: 'Asia/Kolkata' }), mkt, t('2026-10-23T02:29:00Z'), false, 'quiet-hours'],
  // tz problems
  [mk({ timeZone: null }), mkt, t('2026-10-23T18:00:00Z'), false, 'unknown-time-zone'],
  [mk({ timeZone: 'Mars/Base' }), mkt, t('2026-10-23T18:00:00Z'), false, 'unknown-time-zone'],
  [mk({ timeZone: 'UTC' }), mkt, t('2026-10-23T18:00:00Z'), false, 'unknown-time-zone'],
  [mk({ timeZone: '+05:00' }), mkt, t('2026-10-23T18:00:00Z'), false, 'unknown-time-zone'],
  [mk({ timeZone: 42 }), mkt, t('2026-10-23T18:00:00Z'), false, 'unknown-time-zone'],
  // consent
  [mk({ sms: { optedIn: false, optedOutAt: null } }), mkt, t('2026-10-23T18:00:00Z'), false, 'no-consent'],
  [mk({ sms: { optedIn: 'true', optedOutAt: null } }), mkt, t('2026-10-23T18:00:00Z'), false, 'no-consent'],
  [mk({ sms: { optedIn: true, optedOutAt: '2026-10-01T00:00:00Z' } }), mkt, t('2026-10-23T18:00:00Z'), false, 'opted-out'],
  [mk({ sms: { optedIn: true, optedOutAt: 'garbage' } }), mkt, t('2026-10-23T18:00:00Z'), false, 'opted-out'],
  [mk({ sms: { optedIn: true, optedOutAt: '2026-10-01T00:00:00Z' } }), trx, t('2026-10-23T18:00:00Z'), false, 'opted-out'],
  [mk(), { kind: 'marketing', text: 'Sale 20% off' }, t('2026-10-23T18:00:00Z'), false, 'no-opt-out-notice'],
  // transactional ignores consent flag, time of day, tz
  [mk({ sms: { optedIn: false, optedOutAt: null }, timeZone: null }), trx, t('2026-10-23T08:00:00Z'), true, ''],
  [mk(), trx, t('2026-10-24T05:00:00Z'), true, ''],
  [mk(), trx, new Date('x'), true, ''],
  // odd input
  [null, mkt, t('2026-10-23T18:00:00Z'), false, 'invalid-input'],
  [mk(), null, t('2026-10-23T18:00:00Z'), false, 'invalid-input'],
  [mk(), { kind: 'promo', text: 'x' }, t('2026-10-23T18:00:00Z'), false, 'invalid-kind'],
  [mk(), { kind: 'transactional', text: '  ' }, t('2026-10-23T18:00:00Z'), false, 'empty-message'],
  [mk(), mkt, new Date('x'), false, 'invalid-time'],
  [mk(), mkt, '2026-10-23T18:00:00Z', false, 'invalid-time'],
  [mk({ sms: null }), mkt, t('2026-10-23T18:00:00Z'), false, 'no-consent'],
];
let n = 0;
for (const [user, message, now, allowed, rule] of cases) {
  const r = await checkSend({ user, message, now });
  assert.deepEqual(r, { allowed, rule }, `case ${n}: ${JSON.stringify({ user, message, now })}`);
  n++;
}
// never throws
for (const arg of [undefined, null, 5, 'x', {}, { user: new Proxy({}, { get() { throw new Error('boom'); } }) }]) {
  const r = await checkSend(arg);
  assert.equal(r.allowed, false);
}
console.log(`ok ${n} cases`);

